package org.brightstats.stats;

import java.util.*;
import java.util.function.IntConsumer;

/** Hard PLS segmentation using group-relative structural residual distances and actual refits. */
public final class PredictionSegmentation {
    private PredictionSegmentation() {}
    public enum Criterion { ALL_R_SQUARED, TARGET_R_SQUARED, ALL_WEIGHTED_R_SQUARED, TARGET_WEIGHTED_R_SQUARED }
    public enum Initialization { BALANCED_RANDOM, FIMIX, PROVIDED }
    public record Options(int segments,int repetitions,int maxIterations,int searchDepth,int minimumSize,
                          double tolerance,long seed,boolean preSegmentation,Criterion criterion,int target,
                          Initialization initialization,int maximumGroupFits) {
        public Options {
            Objects.requireNonNull(criterion);Objects.requireNonNull(initialization);
            if(segments<1||segments>100||repetitions<1||repetitions>100||maxIterations<1||maxIterations>10000||searchDepth<1||minimumSize<3||!Double.isFinite(tolerance)||tolerance<=0||maximumGroupFits<segments||maximumGroupFits>1000000)
                throw new IllegalArgumentException("Invalid bounded prediction-segmentation settings.");
            if(initialization==Initialization.PROVIDED&&repetitions!=1)throw new IllegalArgumentException("An explicit starting partition requires one start.");
        }
        public static Options defaults(int rows){return new Options(2,3,1000,rows,5,1e-8,295948,false,Criterion.ALL_R_SQUARED,-1,Initialization.BALANCED_RANDOM,100000);}
    }
    public record Segment(int index,int[] rows,PlsSem.Fit fit,double[] means,double[] scales) {
        public Segment {rows=rows.clone();means=means.clone();scales=scales.clone();}
        @Override public int[] rows(){return rows.clone();}@Override public double[] means(){return means.clone();}@Override public double[] scales(){return scales.clone();}
    }
    public record Step(int iteration,String phase,double objective,int considered,int acceptedRow,int source,int target,double improvement) {}
    public record Start(int index,long seed,boolean converged,double objective,int iterations,int groupFits,String failure) {}
    public record Result(Options options,PlsSem.Options modelOptions,int observations,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,
                         PlsSem.Fit pooled,int bestStart,boolean converged,double pooledObjective,double objective,
                         int[] initialAssignments,int[] assignments,List<Segment> segments,double[][] distances,List<Step> trace,
                         List<Start> starts,int rejectedCandidates,int zeroResidualTerms,List<String> warnings) {
        public Result {blocks=List.copyOf(blocks);edges=List.copyOf(edges);initialAssignments=initialAssignments.clone();assignments=assignments.clone();segments=List.copyOf(segments);distances=Matrices.copy(distances);trace=List.copyOf(trace);starts=List.copyOf(starts);warnings=List.copyOf(warnings);}
        @Override public int[] initialAssignments(){return initialAssignments.clone();}@Override public int[] assignments(){return assignments.clone();}@Override public double[][] distances(){return Matrices.copy(distances);}
    }
    private record State(int[] assignments,List<Segment> segments,double objective) {}
    private record Move(int row,int source,int target,double gain) {}
    private record Distance(double[][] values,int zeroTerms) {}
    private static final class BudgetExceeded extends IllegalArgumentException {BudgetExceeded(){super("Configured group-fit budget exhausted; selected solution remains provisional.");}}
    private static final class Work {
        final double[][] data;final List<PlsSem.Block> blocks;final List<PlsSem.Edge> edges;final PlsSem.Options modelOptions;final Options options;final int n,width;final boolean[] used;int fits,rejected;
        Work(double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options modelOptions,Options options){this.data=Matrices.copy(data);this.blocks=List.copyOf(blocks);this.edges=List.copyOf(edges);this.modelOptions=Objects.requireNonNull(modelOptions);this.options=Objects.requireNonNull(options);width=Matrices.width(data,3);n=data.length;used=new boolean[width];for(var block:blocks)for(int column:block.columns()){if(column<0||column>=width)throw new IllegalArgumentException("Invalid indicator column.");used[column]=true;}if(options.searchDepth()>n||(long)options.segments()*options.minimumSize()>n||(long)n*options.segments()*Math.max(1,edges.size())>20000000L)throw new IllegalArgumentException("Search depth, minimum class sizes or distance dimensions exceed available data/bounds.");if(edges.isEmpty())throw new IllegalArgumentException("A structural path is required.");if(targetOnly(options.criterion())&&(options.target()<0||options.target()>=blocks.size()||edges.stream().noneMatch(edge->edge.target()==options.target())))throw new IllegalArgumentException("Choose an endogenous target for target-specific optimization.");int[] parents=new int[blocks.size()];for(var edge:edges){if(edge.target()<0||edge.target()>=blocks.size())throw new IllegalArgumentException("Invalid structural target.");parents[edge.target()]++;}if(options.minimumSize()<=Arrays.stream(parents).max().orElse(0)+1)throw new IllegalArgumentException("Minimum segment size must exceed structural predictor count plus one.");}
        State evaluate(int[] assignments){Matrices.interrupted();if(assignments==null||assignments.length!=n)throw new IllegalArgumentException("Partition length differs from observations.");int[] counts=new int[options.segments()];for(int group:assignments){if(group<0||group>=counts.length)throw new IllegalArgumentException("Partition labels must be zero-based segment indexes.");counts[group]++;}for(int count:counts)if(count<options.minimumSize())throw new IllegalArgumentException("Starting or proposed segment is smaller than the configured minimum.");List<Segment> segments=new ArrayList<>();double value=0;for(int group=0;group<counts.length;group++){Matrices.interrupted();if(fits>=options.maximumGroupFits())throw new BudgetExceeded();fits++;int selected=group;int[] rows=java.util.stream.IntStream.range(0,n).filter(row->assignments[row]==selected).toArray();double[][] subset=Arrays.stream(rows).mapToObj(row->data[row].clone()).toArray(double[][]::new);var fit=PlsSem.fit(subset,blocks,edges,modelOptions);if(!fit.converged())throw new IllegalArgumentException("A segment PLS model did not converge.");double[] means=new double[width],scales=new double[width];Arrays.fill(scales,1);for(int column=0;column<width;column++)if(used[column]){for(int row=0;row<subset.length;row++)means[column]+=(subset[row][column]-means[column])/(row+1);double sum=0;for(double[] row:subset){double centered=row[column]-means[column];sum+=centered*centered;}scales[column]=Math.sqrt(sum/subset.length);if(!(scales[column]>0)||!Double.isFinite(scales[column]))throw new IllegalArgumentException("Segment contains an unscalable indicator.");}segments.add(new Segment(group,rows,fit,means,scales));value+=objective(fit.rSquared(),edges,options.criterion(),options.target())*(weighted(options.criterion())?(double)rows.length/n:1);}if(!Double.isFinite(value))throw new IllegalArgumentException("Segment objective is nonfinite.");return new State(assignments.clone(),List.copyOf(segments),value);}
        Distance distances(State state){double[][] values=new double[n][options.segments()];int zeros=0;Set<Integer> responses=new TreeSet<>();for(var edge:edges)responses.add(edge.target());for(var origin:state.segments()){double[][] scores=origin.fit().scores();for(var candidate:state.segments()){Matrices.interrupted();double[][] weights=candidate.fit().weights(),paths=candidate.fit().pathCoefficients();for(int response:responses){double[] errors=new double[origin.rows.length];double sum=0;for(int local=0;local<origin.rows.length;local++){int row=origin.rows[local];double estimate=0;for(var edge:edges)if(edge.target()==response){var block=blocks.get(edge.source());int[] columns=block.columns();double score=0;for(int j=0;j<columns.length;j++)score+=(data[row][columns[j]]-origin.means[columns[j]])/origin.scales[columns[j]]*weights[edge.source()][j];estimate+=score*paths[edge.source()][response];}double error=estimate-scores[local][response];errors[local]=error;sum+=error*error;}if(!Double.isFinite(sum))throw new IllegalArgumentException("Structural distance exceeded finite range.");if(sum==0){zeros++;continue;}double scale=Math.sqrt(sum);for(int local=0;local<origin.rows.length;local++)values[origin.rows[local]][candidate.index()]+=Math.abs(errors[local])/scale;}}}return new Distance(values,zeros);}
    }
    private static boolean targetOnly(Criterion criterion){return criterion==Criterion.TARGET_R_SQUARED||criterion==Criterion.TARGET_WEIGHTED_R_SQUARED;}
    private static boolean weighted(Criterion criterion){return criterion==Criterion.ALL_WEIGHTED_R_SQUARED||criterion==Criterion.TARGET_WEIGHTED_R_SQUARED;}
    public static double objective(double[] rSquared,List<PlsSem.Edge> edges,Criterion criterion,int target){Set<Integer> responses=new HashSet<>();for(var edge:edges)responses.add(edge.target());if(targetOnly(criterion)){if(!responses.contains(target))throw new IllegalArgumentException("Objective target must be endogenous.");return rSquared[target];}double value=0;for(int response:responses)value+=rSquared[response];return value;}
    public static int[] balanced(int n,int groups,long seed){if(groups<1||n<groups||n>1000000)throw new IllegalArgumentException("Invalid balanced partition size.");List<Integer> order=new ArrayList<>();for(int row=0;row<n;row++)order.add(row);Collections.shuffle(order,new Random(seed));int[] labels=new int[n];for(int index=0;index<n;index++)labels[order.get(index)]=index%groups;return labels;}
    public static Result fit(double[][] data,List<PlsSem.Block> blocks,List<PlsSem.Edge> edges,PlsSem.Options modelOptions,Options options,int[] supplied,FiniteMixture.Options mixtureOptions,IntConsumer progress){
        Work work=new Work(data,blocks,edges,modelOptions,options);var pooled=PlsSem.fit(data,blocks,edges,modelOptions);if(!pooled.converged())throw new IllegalArgumentException("Pooled PLS model did not converge.");if(options.initialization()==Initialization.PROVIDED&&supplied==null||options.initialization()!=Initialization.PROVIDED&&supplied!=null)throw new IllegalArgumentException("Provided partition and initialization selection disagree.");if(options.initialization()==Initialization.FIMIX&&(mixtureOptions==null||mixtureOptions.segments()!=options.segments()))throw new IllegalArgumentException("FIMIX initialization needs matching mixture segment settings.");long[] seeds=ReferenceResampling.seeds(options.seed(),options.repetitions());List<Start> starts=new ArrayList<>();List<String> warnings=new ArrayList<>();State best=null;List<Step> bestTrace=List.of();int[] bestInitial=null;boolean bestConverged=false;int bestIndex=-1;int totalRejected=0;
        for(int start=0;start<options.repetitions();start++){Matrices.interrupted();work.fits=0;work.rejected=0;State current=null;int[] initial=null;List<Step> trace=new ArrayList<>();boolean converged=false;String failure=null;int iteration=0;try{initial=switch(options.initialization()){case BALANCED_RANDOM->balanced(data.length,options.segments(),seeds[start]);case PROVIDED->supplied.clone();case FIMIX->{var m=mixtureOptions;var seeded=new FiniteMixture.Options(m.segments(),m.repetitions(),m.maxIterations(),m.tolerance(),seeds[start],m.intercept(),m.varianceFloor(),m.minimumMass(),m.initialization(),m.stopping());yield PlsMixture.fit(data,blocks,edges,modelOptions,seeded,false,null).mixture().assignments();}};current=work.evaluate(initial);trace.add(new Step(0,"Initial",current.objective(),0,-1,-1,-1,0));if(options.preSegmentation()){var distances=work.distances(current).values();int[] proposed=current.assignments().clone();for(int row=0;row<data.length;row++)for(int group=0;group<options.segments();group++)if(distances[row][group]<distances[row][proposed[row]])proposed[row]=group;try{State pre=work.evaluate(proposed);trace.add(new Step(0,"Pre-segmentation (may reduce objective)",pre.objective(),data.length,-1,-1,-1,pre.objective()-current.objective()));current=pre;}catch(BudgetExceeded limit){throw limit;}catch(IllegalArgumentException invalid){work.rejected++;trace.add(new Step(0,"Invalid pre-segmentation skipped",current.objective(),data.length,-1,-1,-1,0));}}
                for(iteration=1;iteration<=options.maxIterations();iteration++){Matrices.interrupted();double[][] distances=work.distances(current).values();List<Move> moves=new ArrayList<>();for(int row=0;row<data.length;row++){int source=current.assignments()[row],target=source;for(int group=0;group<options.segments();group++)if(distances[row][group]<distances[row][target])target=group;if(target!=source)moves.add(new Move(row,source,target,distances[row][source]-distances[row][target]));}moves.sort(Comparator.comparingDouble(Move::gain).reversed().thenComparingInt(Move::row));State accepted=null;Move selected=null;int considered=0;for(var move:moves){if(considered>=options.searchDepth())break;considered++;if(current.segments().get(move.source()).rows.length<=options.minimumSize()){work.rejected++;continue;}int[] proposed=current.assignments().clone();proposed[move.row()]=move.target();try{State candidate=work.evaluate(proposed);if(candidate.objective()>current.objective()+options.tolerance()){accepted=candidate;selected=move;break;}}catch(BudgetExceeded limit){throw limit;}catch(IllegalArgumentException invalid){work.rejected++;}}
                    if(accepted==null){converged=true;trace.add(new Step(iteration,"Search exhausted",current.objective(),considered,-1,-1,-1,0));break;}trace.add(new Step(iteration,"Accepted move",accepted.objective(),considered,selected.row(),selected.source(),selected.target(),accepted.objective()-current.objective()));current=accepted;
                }
            }catch(IllegalArgumentException invalid){failure=invalid.getMessage();}
            if(iteration>options.maxIterations())iteration=options.maxIterations();double value=current==null?Double.NaN:current.objective();starts.add(new Start(start,seeds[start],converged,value,iteration,work.fits,failure));totalRejected+=work.rejected;if(current!=null&&(best==null||converged&&!bestConverged||converged==bestConverged&&current.objective()>best.objective())){best=current;bestInitial=initial;bestTrace=List.copyOf(trace);bestConverged=converged;bestIndex=start;}if(progress!=null)progress.accept(start+1);
        }
        if(best==null)throw new IllegalArgumentException("No valid prediction-segmentation start: "+starts.stream().map(Start::failure).filter(Objects::nonNull).findFirst().orElse("unknown failure"));var distances=work.distances(best);warnings.add("Hard assignments discard class uncertainty. Segment PLS models are refitted; their in-sample R² objective is not an out-of-sample predictive validation or a causal guarantee. Repeated starts mitigate local optima but do not establish a global solution.");warnings.add("Distances combine structural residual shares normalized separately within each origin segment and candidate model. Origin-segment standardized indicators/response scores are combined with candidate weights/path coefficients; target-specific objectives still rank candidates using all endogenous distances.");warnings.add("After optional pre-segmentation, only objective increases exceeding the configured tolerance are accepted. Pre-segmentation can reduce the objective; invalid partitions are skipped and recorded. Convergence means no improving move among the requested ranked candidates, not all possible partitions.");warnings.add("Balanced random initialization uses a seeded shuffle, differing from the recovered reference's rejection-sampled row ordering. Standardized PLS scores only; raw/mean-centered POS and complete native numerical parity remain open.");if(!bestConverged)warnings.add("Selected start is provisional: iteration or group-fit limits prevented search exhaustion.");if(options.searchDepth()<data.length)warnings.add("Reduced search depth restricts the neighborhood examined; repeat with full sample search depth for final assessment.");if(totalRejected>0)warnings.add("Invalid or undersized candidate partitions were rejected without replacement; see rejectedCandidates and start failures.");if(distances.zeroTerms()>0)warnings.add("Exactly zero residual-sum distance terms contribute zero, avoiding undefined 0/0; this is an explicit robustness policy.");return new Result(options,modelOptions,data.length,blocks,edges,pooled,bestIndex,bestConverged,objective(pooled.rSquared(),edges,options.criterion(),options.target()),best.objective(),bestInitial,best.assignments(),best.segments(),distances.values(),bestTrace,starts,totalRejected,distances.zeroTerms(),warnings);
    }
}
